# Basic spaces and surfaces. All text fields are LaTeX-compatible: math in $...$, plain prose otherwise.
# p order: compact, connected, path-connected, Hausdorff, manifold, orientable, simply connected, contractible
Z = r"\mathbb{Z}"

D1 = [
dict(id="point", n="The point", sym=r"\{*\}", cat="Basic",
 d="One point. Every contractible space is homotopy equivalent to it.",
 p=[1,1,1,1,1,1,1,1], pi="1", H=rf"{Z},\ 0,\ 0,\dots", chi="1",
 how="Only the constant loop exists.",
 why="Reference point for contractibility and for the dimension axiom of homology.",
 ps=[("Everything", "A one-point space is finite, hence compact. Hausdorff holds vacuously. It is $\\mathbb{R}^0$, so it is a $0$-manifold.")],
 alg=[("Fundamental group", "There is exactly one map $[0,1]\\to\\{*\\}$, so $\\pi_1=1$."),
      ("Homology from the definition", "There is one singular $n$-simplex $\\sigma_n$ in each degree, so $C_n=\\mathbb{Z}$. Its boundary is $\\partial\\sigma_n=\\sum_{i=0}^n(-1)^i\\sigma_{n-1}$, which is $\\sigma_{n-1}$ for $n$ even and $n>0$, and $0$ for $n$ odd. The chain complex is $\\cdots\\xrightarrow{\\ 1\\ }\\mathbb{Z}\\xrightarrow{\\ 0\\ }\\mathbb{Z}\\xrightarrow{\\ 1\\ }\\mathbb{Z}\\xrightarrow{\\ 0\\ }\\mathbb{Z}\\to0$, which is exact except at degree $0$. So $H_0=\\mathbb{Z}$ and $H_n=0$ for $n>0$.")]),

dict(id="rn", n="Euclidean space", sym=r"\mathbb{R}^n", cat="Basic",
 d="The model space for manifolds.",
 p=[0,1,1,1,1,1,1,1], pi="1", H=rf"{Z},\ 0,\ 0,\dots", chi="1",
 how="Straight-line homotopy to the origin.",
 why="Contractible but not compact. Compare the long line, which has trivial homotopy groups yet is not contractible.",
 ps=[("Not compact", "The open balls $B(0,k)$, $k=1,2,\\dots$, cover $\\mathbb{R}^n$, and any finite subfamily lies in one ball. Equivalently, Heine–Borel fails because $\\mathbb{R}^n$ is unbounded."),
     ("Path-connected, Hausdorff", "The segment $t\\mapsto(1-t)x+ty$ joins $x$ to $y$. Distinct points at distance $d$ have disjoint balls of radius $d/2$."),
     ("Manifold, orientable", "The identity is a global chart, and a single chart is an oriented atlas.")],
 alg=[("Contraction", "$H(x,t)=(1-t)x$ is continuous with $H_0=\\mathrm{id}$ and $H_1$ constant. So $\\mathbb{R}^n\\simeq\\{*\\}$ and every homotopy invariant agrees with that of a point.")]),

dict(id="disk", n="Closed disk", sym=r"D^n", cat="Basic",
 d=r"The unit ball $\{x\in\mathbb{R}^n:|x|\le 1\}$.",
 p=[1,1,1,1,"b",1,1,1], pi="1", H=rf"{Z},\ 0,\dots", chi="1",
 how="Convex, so straight-line homotopy.",
 why=r"Brouwer's fixed point theorem: $S^{n-1}$ is not a retract of $D^n$, proved with $H_{n-1}$.",
 ps=[("Compact", "Closed and bounded in $\\mathbb{R}^n$, so compact by Heine–Borel."),
     ("Manifold with boundary", "Interior points have Euclidean balls as neighborhoods. A point with $|x|=1$ has a neighborhood homeomorphic to an open subset of the half-space $\\{x_n\\ge0\\}$, for example via radial coordinates near the boundary sphere.")],
 alg=[("Contraction", "$D^n$ is convex, so $H(x,t)=(1-t)x$ stays in $D^n$."),
      ("Brouwer", "If $r:D^n\\to S^{n-1}$ were a retraction, then $S^{n-1}\\hookrightarrow D^n\\xrightarrow{r}S^{n-1}$ is the identity. Apply $H_{n-1}$ (with $n\\ge2$): the identity of $\\mathbb{Z}$ factors through $H_{n-1}(D^n)=0$, a contradiction. A map $f:D^n\\to D^n$ without fixed points would give such a retraction by sending $x$ to where the ray from $f(x)$ through $x$ meets the boundary.")]),

dict(id="circle", n="Circle", sym=r"S^1", cat="Basic",
 d=r"The unit circle in $\mathbb{R}^2$, or $\mathbb{R}/\mathbb{Z}$.",
 p=[1,1,1,1,1,1,0,0], pi=Z, H=rf"{Z},\ {Z},\ 0,\dots", chi="0",
 how=r"Lift loops through the covering $\mathbb{R}\to S^1$; the endpoint of the lift is the winding number.",
 why="The first nontrivial computation. It gives the fundamental theorem of algebra and Brouwer in dimension 2.",
 ps=[("Compact, connected", "Closed and bounded in $\\mathbb{R}^2$. It is the continuous image of $[0,1]$ under $t\\mapsto e^{2\\pi it}$, so it is path-connected."),
     ("1-manifold", "Removing the point $1$ leaves an open arc homeomorphic to $(0,1)$; removing $-1$ gives a second chart. The transition maps are translations, so the atlas is oriented.")],
 alg=[("Covering", "$p:\\mathbb{R}\\to S^1$, $p(t)=e^{2\\pi it}$, is a covering map: each small arc has preimage a disjoint union of intervals, each mapped homeomorphically."),
      ("Degree map", "A loop $\\gamma$ at $1$ lifts uniquely to $\\tilde\\gamma$ with $\\tilde\\gamma(0)=0$, and $\\tilde\\gamma(1)\\in\\mathbb{Z}$. Homotopic loops have lifts with the same endpoint (homotopy lifting), so $\\deg[\\gamma]=\\tilde\\gamma(1)$ is well defined."),
      ("Isomorphism", "Homomorphism: the lift of $\\gamma\\cdot\\delta$ is $\\tilde\\gamma$ followed by $\\tilde\\delta+\\tilde\\gamma(1)$. Surjective: $t\\mapsto e^{2\\pi int}$ has degree $n$. Injective: if $\\tilde\\gamma(1)=0$, then $\\tilde\\gamma$ is a loop in the contractible $\\mathbb{R}$; push a null-homotopy down by $p$."),
      ("Homology", "CW structure: one $0$-cell $v$, one $1$-cell $a$. Then $\\partial a=v-v=0$, so $H_0=H_1=\\mathbb{Z}$ and $\\chi=1-1=0$.")]),

dict(id="sphere", n="Sphere", sym=r"S^n,\ n\ge 2", cat="Basic",
 d=r"The unit sphere in $\mathbb{R}^{n+1}$.",
 p=[1,1,1,1,1,1,1,0], pi="1", H=rf"H_0=H_n={Z},\ \text{{else }}0", chi="1+(-1)^n",
 how="Van Kampen with two hemispheres whose overlap is path-connected.",
 why=r"Simply connected but not contractible: the first place $\pi_1$ is too weak. $\pi_3(S^2)\cong\mathbb{Z}$ through the Hopf map.",
 ps=[("Compact, Hausdorff", "Closed and bounded subset of $\\mathbb{R}^{n+1}$."),
     ("Path-connected", "Two non-antipodal points are joined by the shorter great-circle arc; antipodal points go through any third point."),
     ("Manifold, orientable", "Stereographic projection from the north and south poles gives two charts onto $\\mathbb{R}^n$. The transition map is inversion $x\\mapsto x/|x|^2$ composed with a reflection, and the charts can be chosen so the Jacobian determinant is positive.")],
 alg=[("Fundamental group", "Let $U=S^n\\setminus\\{N\\}$ and $V=S^n\\setminus\\{S\\}$. Both are homeomorphic to $\\mathbb{R}^n$, and $U\\cap V\\cong\\mathbb{R}^n\\setminus\\{0\\}\\simeq S^{n-1}$, which is path-connected for $n\\ge2$. Van Kampen gives $\\pi_1(S^n)\\cong 1*1=1$. For $n=1$ the overlap has two components and the theorem does not apply, which is why $S^1$ is different."),
      ("Homology", "CW structure $e^0\\cup e^n$. The cellular chain complex is $\\mathbb{Z}$ in degrees $0$ and $n$ and zero elsewhere, so every differential vanishes. Alternatively, Mayer–Vietoris with the same $U,V$ gives $\\tilde H_k(S^n)\\cong\\tilde H_{k-1}(S^{n-1})$."),
      ("Euler characteristic", "$\\chi=1+(-1)^n$: $2$ for even spheres and $0$ for odd ones. Hairy ball: a nowhere-zero vector field on $S^n$ forces $\\chi=0$, so even spheres have none."),
      ("Higher homotopy", "$\\pi_k(S^n)=0$ for $k<n$ (cellular approximation) and $\\pi_n(S^n)\\cong\\mathbb{Z}$ by degree. Above dimension $n$ the groups are hard; see the table at the end.")]),

dict(id="annulus", n="Annulus and solid torus", sym=r"S^1\times I,\ \ S^1\times D^2", cat="Basic",
 d="Both deformation retract onto a core circle.",
 p=[1,1,1,1,"b",1,0,0], pi=Z, H=rf"{Z},\ {Z},\ 0,\dots", chi="0",
 how=r"Deformation retract onto $S^1$.",
 why=r"$\pi_1$ ignores dimension. The solid torus is half of the genus-one Heegaard splitting of $S^3$ and of every lens space.",
 ps=[("Compact", "Products of compact spaces."),
     ("Manifold with boundary", "The annulus is a surface with two boundary circles. The solid torus is a 3-manifold whose boundary is a torus."),
     ("Orientable", "Both embed as codimension-zero submanifolds of $\\mathbb{R}^2$ and $\\mathbb{R}^3$, which are orientable.")],
 alg=[("Deformation retraction", "In polar coordinates on $\\{1\\le r\\le2\\}$, $H((r,\\theta),t)=((1-t)r+t,\\theta)$ pushes everything to $r=1$. For $S^1\\times D^2$, shrink the disk factor: $(z,w,t)\\mapsto(z,(1-t)w)$."),
      ("Invariants", "Homotopy equivalent to $S^1$, so $\\pi_1=\\mathbb{Z}$, $H_1=\\mathbb{Z}$, and $\\chi=0$.")]),

dict(id="mobius", n="Möbius band", sym=r"M", cat="Basic",
 d=r"$[0,1]\times[0,1]$ with $(0,y)\sim(1,1-y)$.",
 p=[1,1,1,1,"b",0,0,0], pi=Z, H=rf"{Z},\ {Z},\ 0", chi="0",
 how="Retract onto the core circle.",
 why=r"Same homotopy type as the annulus but not homeomorphic: one boundary circle, not two. Gluing a disk to its boundary gives $\mathbb{RP}^2$.",
 ps=[("Compact, Hausdorff", "Quotient of a compact square, so compact. It embeds in $\\mathbb{R}^3$ by $(\\theta,s)\\mapsto((1+s\\cos\\frac\\theta2)\\cos\\theta,(1+s\\cos\\frac\\theta2)\\sin\\theta,s\\sin\\frac\\theta2)$ with $|s|\\le\\frac12$, so it is Hausdorff."),
     ("Non-orientable", "Carry a small oriented frame once around the core circle $y=\\frac12$. The gluing $(0,y)\\sim(1,1-y)$ flips the $y$-direction, so the frame returns reflected."),
     ("One boundary circle", "The edge $y=0$ is glued at $x=1$ to the start of the edge $y=1$, and vice versa, so the two edges join into a single circle of twice the length.")],
 alg=[("Deformation retraction", "$H((x,y),t)=(x,(1-t)y+\\frac t2)$. It respects the gluing: $1-y\\mapsto(1-t)(1-y)+\\frac t2=1-[(1-t)y+\\frac t2]$. At $t=1$ everything lies on the core circle."),
      ("The boundary wraps twice", "Under the retraction the boundary circle traverses the core twice, so $H_1(\\partial M)\\to H_1(M)$ is multiplication by $2$. The annulus boundary components map by $\\pm1$, which tells the two spaces apart.")]),

dict(id="torus", n="Torus", sym=r"T^2=S^1\times S^1", cat="Surfaces",
 d=r"A square with opposite sides identified by the word $aba^{-1}b^{-1}$.",
 p=[1,1,1,1,1,1,0,0], pi=rf"{Z}^2", H=rf"{Z},\ {Z}^2,\ {Z}", chi="0",
 how=r"$\pi_1(X\times Y)\cong\pi_1X\times\pi_1Y$, or van Kampen on the CW structure.",
 why=r"The universal cover $\mathbb{R}^2$ with deck group $\mathbb{Z}^2$ is the cleanest example of the covering correspondence.",
 ps=[("Compact, Hausdorff", "Product of two compact Hausdorff spaces."),
     ("Manifold, orientable", "Products of charts of $S^1$ give charts of $T^2$. In the square model, every edge appears once as $x$ and once as $x^{-1}$, which is the polygon criterion for orientability.")],
 alg=[("Fundamental group", "A loop in $X\\times Y$ is a pair of loops, and homotopies act coordinatewise, so $\\pi_1(T^2)\\cong\\mathbb{Z}\\times\\mathbb{Z}$. In the square, the relation $aba^{-1}b^{-1}=1$ is the boundary of the 2-cell."),
      ("Cellular homology", "One $0$-cell $v$, $1$-cells $a,b$, one $2$-cell $e$. Then $\\partial a=\\partial b=v-v=0$ and $\\partial e=a+b-a-b=0$. All differentials vanish, so $H=\\mathbb{Z},\\mathbb{Z}^2,\\mathbb{Z}$ and $\\chi=1-2+1=0$."),
      ("Universal cover", "$\\mathbb{R}^2\\to\\mathbb{R}^2/\\mathbb{Z}^2$. Since $\\mathbb{R}^2$ is contractible, $T^2$ is aspherical: $\\pi_k(T^2)=0$ for $k\\ge2$.")]),

dict(id="ntorus", n="n-torus", sym=r"T^n", cat="Surfaces",
 d=r"Product of $n$ circles; $\mathbb{R}^n/\mathbb{Z}^n$.",
 p=[1,1,1,1,1,1,0,0], pi=rf"{Z}^n", H=rf"H_k\cong {Z}^{{\binom nk}}", chi="0",
 how="Product formula; homology from the product cell structure.",
 why=r"$T^n$ is a $K(\mathbb{Z}^n,1)$. The binomial Betti numbers are a good Künneth exercise.",
 ps=[("Compact, manifold, orientable", "Finite product of compact orientable manifolds. The cube $[0,1]^n$ with opposite faces glued by translations is another model.")],
 alg=[("Fundamental group", "Product formula, or the covering $\\mathbb{R}^n\\to T^n$ with deck group $\\mathbb{Z}^n$."),
      ("Homology", "The product CW structure has one $k$-cell for each $k$-element subset of the $n$ coordinates, so $\\binom nk$ cells in degree $k$. Each circle factor has zero differential, and the product differential is built from these, so it vanishes. Hence $H_k\\cong\\mathbb{Z}^{\\binom nk}$."),
      ("Euler characteristic", "$\\chi=\\sum_k(-1)^k\\binom nk=(1-1)^n=0$.")]),

dict(id="genusg", n="Orientable surface of genus g", sym=r"\Sigma_g,\ g\ge 1", cat="Surfaces",
 d=r"Connected sum of $g$ tori; a $4g$-gon with word $a_1b_1a_1^{-1}b_1^{-1}\cdots a_gb_ga_g^{-1}b_g^{-1}$.",
 p=[1,1,1,1,1,1,0,0], pi=r"\langle a_1,b_1,\dots,a_g,b_g \mid [a_1,b_1]\cdots[a_g,b_g]\rangle", H=rf"{Z},\ {Z}^{{2g}},\ {Z}", chi="2-2g",
 how="Van Kampen: the 1-skeleton is a wedge of 2g circles and the 2-cell adds one relation.",
 why=r"For $g\ge2$ the group is non-abelian and hyperbolic. $H_1=\mathbb{Z}^{2g}$ is its abelianization, a concrete case of Hurewicz.",
 ps=[("Compact, Hausdorff", "Quotient of a compact polygon. It embeds in $\\mathbb{R}^3$ as the surface of a $g$-holed doughnut, so it is Hausdorff."),
     ("2-manifold", "Interior points of the polygon have disk neighborhoods. An edge point gets two half-disks glued along a diameter. All $4g$ vertices go to one point, and their $4g$ corner sectors fit together around it into a full disk."),
     ("Orientable", "Each edge label appears once with exponent $+1$ and once with $-1$, so the gluings reverse the boundary direction and the polygon's orientation extends across every edge.")],
 alg=[("Van Kampen", "Let $U$ be the open 2-cell and $V$ the complement of its center. $U$ is contractible, $V$ deformation retracts onto the 1-skeleton (a wedge of $2g$ circles, so $\\pi_1(V)=F_{2g}$), and $U\\cap V$ is an annulus whose generator maps to the boundary word. So $\\pi_1=F_{2g}/\\langle\\langle[a_1,b_1]\\cdots[a_g,b_g]\\rangle\\rangle$."),
      ("Cellular homology", "One $0$-cell, $2g$ $1$-cells, one $2$-cell. The boundary of the 2-cell is $\\sum_i(a_i+b_i-a_i-b_i)=0$, and the $1$-cells are loops. All differentials vanish."),
      ("Euler characteristic", "$\\chi=1-2g+1=2-2g$. Since $H_1=\\mathbb{Z}^{2g}$ determines $g$, different genera give non-homeomorphic surfaces.")]),

dict(id="rp2", n="Real projective plane", sym=r"\mathbb{RP}^2", cat="Surfaces",
 d=r"$S^2$ with antipodal points identified; a disk with antipodal boundary points identified.",
 p=[1,1,1,1,1,0,0,0], pi=rf"{Z}/2", H=rf"{Z},\ {Z}/2,\ 0", chi="1",
 how=r"Two-sheeted universal cover $S^2\to\mathbb{RP}^2$.",
 why="The smallest nontrivial finite fundamental group and the first torsion in homology. It does not embed in $\\mathbb{R}^3$.",
 ps=[("Compact", "Continuous image of $S^2$."),
     ("Hausdorff", "If $[x]\\ne[y]$, choose $\\varepsilon$ smaller than the distances between $\\pm x$ and $\\pm y$. The images of the four $\\varepsilon$-balls around $\\pm x,\\pm y$ are disjoint open sets."),
     ("2-manifold", "A small cap on $S^2$ contains no antipodal pair, so it maps homeomorphically onto its image."),
     ("Non-orientable", "A neighborhood of a projective line (the image of a great circle) is a Möbius band.")],
 alg=[("Fundamental group", "$p:S^2\\to\\mathbb{RP}^2$ is a covering with deck group $\\{\\pm1\\}$. $S^2$ is simply connected, so it is the universal cover and $\\pi_1\\cong\\mathbb{Z}/2$. The generator is the image of a path from a point to its antipode."),
      ("Cellular homology", "Cells $e^0,e^1,e^2$, with $e^2$ attached along the word $aa$. The chain complex is $0\\to\\mathbb{Z}\\xrightarrow{\\ 2\\ }\\mathbb{Z}\\xrightarrow{\\ 0\\ }\\mathbb{Z}\\to0$. So $H_0=\\mathbb{Z}$, $H_1=\\mathbb{Z}/2$, and $H_2=\\ker(\\times2)=0$."),
      ("Euler characteristic", "$\\chi=1-1+1=1$, consistent with $\\chi(S^2)=2\\chi(\\mathbb{RP}^2)$ for a 2-sheeted cover.")]),

dict(id="klein", n="Klein bottle", sym=r"K", cat="Surfaces",
 d=r"A square with word $abab^{-1}$; two Möbius bands glued along their boundaries.",
 p=[1,1,1,1,1,0,0,0], pi=r"\langle a,b\mid abab^{-1}\rangle", H=rf"{Z},\ {Z}\oplus{Z}/2,\ 0", chi="0",
 how="Van Kampen on the square, then abelianize.",
 why=r"Same Euler characteristic as the torus; homology tells them apart. $\pi_1$ is non-abelian but contains $\mathbb{Z}^2$ with index 2.",
 ps=[("Compact, Hausdorff", "Quotient of a square; it embeds in $\\mathbb{R}^4$, so it is Hausdorff. In $\\mathbb{R}^3$ it can only be immersed."),
     ("2-manifold, non-orientable", "The polygon argument gives a manifold. The edge $a$ appears twice with the same exponent, so a strip across it is a Möbius band.")],
 alg=[("Fundamental group", "One vertex, edges $a,b$, and a 2-cell attached along $abab^{-1}$. Van Kampen gives $\\langle a,b\\mid abab^{-1}\\rangle$, equivalently $bab^{-1}=a^{-1}$."),
      ("Non-abelian", "$\\pi_1$ is torsion-free (the universal cover is $\\mathbb{R}^2$), so $a\\ne a^{-1}$, and $bab^{-1}=a^{-1}\\ne a$."),
      ("Torus double cover", "$b^2ab^{-2}=ba^{-1}b^{-1}=a$, so $a$ and $b^2$ commute. The subgroup $\\langle a,b^2\\rangle\\cong\\mathbb{Z}^2$ has index $2$ and corresponds to a torus double cover."),
      ("Cellular homology", "$\\partial a=\\partial b=0$ and $\\partial e=a+b+a-b=2a$. So $H_1=\\mathbb{Z}\\langle a,b\\rangle/\\langle 2a\\rangle=\\mathbb{Z}\\oplus\\mathbb{Z}/2$ and $H_2=\\ker\\partial_2=0$. $\\chi=1-2+1=0$.")]),

dict(id="nk", n="Non-orientable surface", sym=r"N_k=\#^k\,\mathbb{RP}^2", cat="Surfaces",
 d=r"Connected sum of $k$ projective planes. $N_1=\mathbb{RP}^2$, $N_2=K$.",
 p=[1,1,1,1,1,0,0,0], pi=r"\langle a_1,\dots,a_k\mid a_1^2a_2^2\cdots a_k^2\rangle", H=rf"{Z},\ {Z}^{{k-1}}\oplus{Z}/2,\ 0", chi="2-k",
 how=r"A $2k$-gon with word $a_1a_1a_2a_2\cdots a_ka_k$.",
 why=r"With $\Sigma_g$ this completes the classification of closed surfaces. Exercise: $T^2\#\mathbb{RP}^2\cong N_3$.",
 ps=[("Compact manifold", "Polygon argument as for $\\Sigma_g$."),
     ("Non-orientable", "Each $a_i$ appears twice with the same exponent, so each contributes a Möbius band.")],
 alg=[("Fundamental group", "One vertex, $k$ edges, one 2-cell; van Kampen gives the presentation."),
      ("Homology", "$\\partial e=2(a_1+\\cdots+a_k)$. Change basis to $a_1,\\dots,a_{k-1},s=a_1+\\cdots+a_k$; then $H_1=\\mathbb{Z}^{k-1}\\oplus\\mathbb{Z}/2$ and $H_2=0$."),
      ("Classification", "$\\chi=2-k$. The torsion in $H_1$ separates $N_k$ from every $\\Sigma_g$, and $\\chi$ separates the $N_k$ from each other.")]),
]
